using UnityEngine;
using UnityEngine.UI;
using UnityEditor;

public class SetupCookingScene
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        // === 1. Find objek Masak ===
        var masak = GameObject.Find("Masak");
        if (masak == null)
        {
            // Cari di seluruh hierarchy
            var allGOs = Object.FindObjectsByType<Transform>(FindObjectsSortMode.None);
            foreach (var t in allGOs)
            {
                if (t.name == "Masak")
                {
                    masak = t.gameObject;
                    break;
                }
            }
        }
        if (masak == null) return "ERROR: Objek Masak tidak ditemukan di scene!";
        sb.AppendLine("[OK] Masak ditemukan: " + masak.name);

        // === 2. Tambah BoxCollider jika belum ada ===
        var col = masak.GetComponent<BoxCollider>();
        if (col == null)
        {
            col = masak.AddComponent<BoxCollider>();
            col.isTrigger = true;
            col.size = new Vector3(3f, 3f, 3f);
            col.center = new Vector3(0f, 1f, 0f);
            sb.AppendLine("[OK] BoxCollider ditambahkan (isTrigger=true, size=3x3x3)");
        }
        else
        {
            col.isTrigger = true;
            sb.AppendLine("[OK] BoxCollider sudah ada, set isTrigger=true");
        }

        // === 3. Instantiate CanvasMemasak prefab ===
        var prefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Character/mc/CanvasMemasak.prefab");
        if (prefab == null) return "ERROR: Prefab CanvasMemasak tidak ditemukan!";

        // Cek apakah sudah ada di scene
        var existingCanvas = Object.FindFirstObjectByType<CookingUI>();
        GameObject canvasGO;
        CookingUI cookingUI;

        if (existingCanvas != null)
        {
            canvasGO = existingCanvas.gameObject;
            cookingUI = existingCanvas;
            sb.AppendLine("[OK] CanvasMemasak sudah ada di scene, pakai yang ada");
        }
        else
        {
            canvasGO = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
            cookingUI = canvasGO.GetComponent<CookingUI>();
            sb.AppendLine("[OK] CanvasMemasak di-instantiate ke scene");
        }

        canvasGO.SetActive(false);
        sb.AppendLine("[OK] CanvasMemasak dinonaktifkan (akan diaktifkan oleh CookingTrigger)");

        // === 4. Tambah CookingTrigger ke Masak ===
        var trigger = masak.GetComponent<CookingTrigger>();
        if (trigger == null)
        {
            trigger = masak.AddComponent<CookingTrigger>();
            sb.AppendLine("[OK] CookingTrigger ditambahkan ke Masak");
        }
        else
        {
            sb.AppendLine("[OK] CookingTrigger sudah ada");
        }

        // === 5. Buat Prompt UI (PromptMasak) ===
        // Cari Canvas utama di scene
        Canvas mainCanvas = null;
        var allCanvas = Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None);
        foreach (var c in allCanvas)
        {
            if (c.gameObject != canvasGO && c.renderMode == RenderMode.ScreenSpaceOverlay)
            {
                mainCanvas = c;
                break;
            }
        }

        GameObject promptGO = null;
        if (mainCanvas != null)
        {
            // Cek apakah sudah ada PromptMasak
            var existingPrompt = mainCanvas.transform.Find("PromptMasak");
            if (existingPrompt != null)
            {
                promptGO = existingPrompt.gameObject;
                sb.AppendLine("[OK] PromptMasak sudah ada");
            }
            else
            {
                promptGO = new GameObject("PromptMasak");
                promptGO.transform.SetParent(mainCanvas.transform, false);
                var rt = promptGO.AddComponent<RectTransform>();
                rt.anchorMin = new Vector2(0.5f, 0.15f);
                rt.anchorMax = new Vector2(0.5f, 0.15f);
                rt.sizeDelta = new Vector2(300f, 50f);
                rt.anchoredPosition = Vector2.zero;

                var bg = promptGO.AddComponent<Image>();
                bg.color = new Color(0.05f, 0.05f, 0.1f, 0.85f);

                var textGO = new GameObject("Text");
                textGO.transform.SetParent(promptGO.transform, false);
                var textRT = textGO.AddComponent<RectTransform>();
                textRT.anchorMin = Vector2.zero;
                textRT.anchorMax = Vector2.one;
                textRT.offsetMin = new Vector2(10f, 5f);
                textRT.offsetMax = new Vector2(-10f, -5f);
                var text = textGO.AddComponent<Text>();
                text.text = "[G] Memasak";
                text.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                text.fontSize = 18;
                text.alignment = TextAnchor.MiddleCenter;
                text.color = new Color(0.95f, 0.9f, 0.7f);

                promptGO.SetActive(false);
                sb.AppendLine("[OK] PromptMasak dibuat di Canvas utama");
            }
        }
        else
        {
            sb.AppendLine("[WARN] Canvas utama tidak ditemukan, prompt tidak dibuat");
        }

        // === 6. Wire CookingTrigger ===
        trigger.cookingCanvas = canvasGO;
        trigger.promptUI = promptGO;
        sb.AppendLine("[OK] CookingTrigger di-wire: cookingCanvas + promptUI");

        // === 7. Load dan assign resep ke CookingUI ===
        string recipeFolder = "Assets/Herbal/Recipes";
        string[] recipeNames = { "Jamu Jahe", "Jamu Kunyit", "Jamu Kencur", "Jamu Temulawak", "Wedang Jahe", "Jamu Beras Kencur" };
        var recipes = new System.Collections.Generic.List<CookingRecipe>();

        foreach (var rn in recipeNames)
        {
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(recipeFolder + "/" + rn + ".asset");
            if (recipe != null)
            {
                recipes.Add(recipe);
                sb.AppendLine("[OK] Resep dimuat: " + rn);
            }
            else
            {
                sb.AppendLine("[WARN] Resep tidak ditemukan: " + rn);
            }
        }

        cookingUI.recipes = recipes.ToArray();
        sb.AppendLine("[OK] " + recipes.Count + " resep di-assign ke CookingUI");

        // === 8. Wire CookingUI detail panel references ===
        var bgPanel = canvasGO.transform.Find("Background");
        var mainPanel = bgPanel?.Find("MainPanel");
        var rightPanel = mainPanel?.Find("RightPanel");
        var leftPanel = mainPanel?.Find("LeftPanel");

        if (leftPanel != null)
            cookingUI.leftPanel = leftPanel.GetComponent<RectTransform>();

        if (rightPanel != null)
        {
            var recipeName = rightPanel.Find("RecipeName");
            var recipeDesc = rightPanel.Find("RecipeDesc");
            var foodImage = rightPanel.Find("FoodImage");
            var hpRestore = rightPanel.Find("HPRestore");
            var btnMasak = rightPanel.Find("BtnMasak");

            if (recipeName != null) cookingUI.recipeName = recipeName.GetComponent<Text>();
            if (recipeDesc != null) cookingUI.recipeDescription = recipeDesc.GetComponent<Text>();
            if (foodImage != null) cookingUI.recipeImage = foodImage.GetComponent<Image>();
            if (hpRestore != null) cookingUI.hpRestoreText = hpRestore.GetComponent<Text>();
            if (btnMasak != null) cookingUI.cookButton = btnMasak.GetComponent<Button>();

            // Ingredient slots
            var slots = new System.Collections.Generic.List<GameObject>();
            var icons = new System.Collections.Generic.List<Image>();
            var names = new System.Collections.Generic.List<Text>();
            var amounts = new System.Collections.Generic.List<Text>();

            for (int i = 0; i < 4; i++)
            {
                var slot = rightPanel.Find("IngredientSlot_" + i);
                if (slot != null)
                {
                    slots.Add(slot.gameObject);
                    var icon = slot.Find("Icon");
                    var nameT = slot.Find("Name");
                    var amountT = slot.Find("Amount");
                    icons.Add(icon != null ? icon.GetComponent<Image>() : null);
                    names.Add(nameT != null ? nameT.GetComponent<Text>() : null);
                    amounts.Add(amountT != null ? amountT.GetComponent<Text>() : null);
                }
            }

            cookingUI.ingredientSlots = slots.ToArray();
            cookingUI.ingredientIcons = icons.ToArray();
            cookingUI.ingredientNames = names.ToArray();
            cookingUI.ingredientAmounts = amounts.ToArray();

            sb.AppendLine("[OK] RightPanel references di-wire (" + slots.Count + " ingredient slots)");
        }

        // Wire close button
        var btnClose = bgPanel?.Find("BtnClose");
        if (btnClose != null)
        {
            cookingUI.closeButton = btnClose.GetComponent<Button>();
        }

        // Wire CookingTrigger reference
        cookingUI.cookingTrigger = trigger;
        sb.AppendLine("[OK] CookingUI.cookingTrigger di-wire");

        // === 9. Mark scene dirty ===
        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(
            UnityEngine.SceneManagement.SceneManager.GetActiveScene()
        );
        sb.AppendLine("[OK] Scene marked dirty - siap di-save");

        return sb.ToString();
    }
}
